/* 屏幕常亮 —— 双引擎，安卓 / 苹果 / 微信内置浏览器都吃得下
 *
 * 为什么不能只写 navigator.wakeLock：
 *   Screen Wake Lock API 只在「安全上下文」里存在，也就是 HTTPS 或 localhost。
 *   现场是 http://192.168.2.110:3000，属于非安全上下文，
 *   'wakeLock' in navigator 直接就是 false —— 光靠它等于没写。
 *
 * 所以加第二个引擎：一个 1px 的静音循环视频（NoSleep 那套办法）。
 *   系统只要看到页面里有媒体在播放，就认为你在「用」这台手机，不会主动熄屏。
 *   不需要 HTTPS，iOS Safari / 微信 WKWebView / 安卓 X5 都能用。
 *
 * 两个一起上：谁能用谁上，能用的那个就是当前状态。
 *
 * 用法（第一次必须在用户手势里调用，否则 iOS 会拒绝播放）：
 *   var keeper = new WakeKeeper();
 *   keeper.onChange(function (s) { ... });
 *   keeper.start();
 */
(function (global) {
  'use strict';

  /* 3753 字节的 mp4 / 5.5KB 的 webm，几十毫秒的黑场循环，声音也没有 */
  var MP4_B64 = '';
  var WEBM_B64 = '';

  function b64ToBlob(b64, type) {
    var bin = global.atob(b64);
    var n = bin.length;
    var u8 = new Uint8Array(n);
    for (var i = 0; i < n; i++) u8[i] = bin.charCodeAt(i);
    return new Blob([u8], { type: type });
  }

  var picked = null;
  function pickSource() {
    if (picked) return picked;
    var v = document.createElement('video');
    var mp4 = '';
    var webm = '';
    try { mp4 = v.canPlayType('video/mp4; codecs="avc1.42E01E"'); } catch (e) {}
    try { webm = v.canPlayType('video/webm; codecs="vp8"'); } catch (e) {}
    // canPlayType 返回 '' 才算不支持，'maybe' / 'probably' 都当支持
    if (mp4) picked = { b64: MP4_B64, type: 'video/mp4' };
    else if (webm) picked = { b64: WEBM_B64, type: 'video/webm' };
    else picked = { b64: MP4_B64, type: 'video/mp4' };
    return picked;
  }

  function createVideo() {
    var src = pickSource();
    var url = URL.createObjectURL(b64ToBlob(src.b64, src.type));
    var v = document.createElement('video');
    v.muted = true;
    v.defaultMuted = true;
    v.setAttribute('muted', '');
    v.setAttribute('playsinline', '');
    v.setAttribute('webkit-playsinline', '');
    v.setAttribute('x5-playsinline', '');
    v.setAttribute('x5-video-player-type', 'h5');        // 别让微信接管成原生播放器
    v.setAttribute('x5-video-player-fullscreen', 'false');
    v.setAttribute('aria-hidden', 'true');
    v.loop = true;
    v.autoplay = true;
    v.preload = 'auto';
    v.src = url;
    // 必须留在视口里，且不能用 display:none —— iOS 会认为它没在放
    v.style.cssText =
      'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0.01;' +
      'pointer-events:none;z-index:0;';
    document.body.appendChild(v);
    return v;
  }

  function WakeKeeper() {
    this.video = null;
    this.lock = null;
    this.lockPending = false;
    this.lockDenied = false;
    this.wanted = false;
    this.playBlocked = false;
    this.watching = false;
    this.timer = null;
    this.listeners = [];
  }

  WakeKeeper.prototype.onChange = function (fn) {
    if (typeof fn === 'function') this.listeners.push(fn);
    return this;
  };

  WakeKeeper.prototype._emit = function () {
    var s = this.state();
    for (var i = 0; i < this.listeners.length; i++) {
      try { this.listeners[i](s); } catch (e) {}
    }
  };

  /* 当前状态，给 UI 用 */
  WakeKeeper.prototype.state = function () {
    var v = this.video;
    var playing = !!(v && !v.paused);
    return {
      wanted: this.wanted,
      active: !!(this.lock || playing),
      locked: !!this.lock,          // 走的是系统唤醒锁
      playing: playing,             // 走的是静音视频
      blocked: !!(this.wanted && !this.lock && !playing), // 需要用户再点一下
      broken: !!(this.wanted && !this.video),             // 视频都没造出来，真没辙了
      denied: this.lockDenied,
    };
  };

  WakeKeeper.prototype.start = function () {
    this.wanted = true;
    if (!this.video) {
      try { this.video = createVideo(); } catch (e) { this.video = null; }
    }
    this._play();
    this._lock();
    this._watch();
    return this;
  };

  WakeKeeper.prototype.stop = function () {
    this.wanted = false;
    if (this.lock) {
      try { this.lock.release(); } catch (e) {}
      this.lock = null;
    }
    if (this.video) {
      try { this.video.pause(); } catch (e) {}
    }
    this._emit();
  };

  WakeKeeper.prototype.toggle = function () {
    if (this.wanted) this.stop();
    else this.start();
  };

  WakeKeeper.prototype._play = function () {
    var self = this;
    var v = this.video;
    if (!v) return;
    if (!v.paused) {
      this.playBlocked = false;
      return;
    }
    var p = null;
    try { p = v.play(); } catch (e) { this.playBlocked = true; }
    if (p && typeof p.then === 'function') {
      p.then(function () {
        self.playBlocked = false;
        self._emit();
      })['catch'](function () {
        self.playBlocked = true; // 多半是没在手势里，或者开了低电量模式
        self._emit();
      });
    }
    setTimeout(function () {
      if (!self.wanted) return;
      self.playBlocked = !!(self.video && self.video.paused);
      self._emit();
    }, 700);
  };

  WakeKeeper.prototype._lock = function () {
    var self = this;
    if (this.lock || this.lockPending) return;
    var api = global.navigator && navigator.wakeLock;
    if (!api || typeof api.request !== 'function') return; // 非安全上下文时根本没有
    if (document.visibilityState === 'hidden') return;
    this.lockPending = true;
    try {
      api.request('screen').then(function (l) {
        self.lockPending = false;
        self.lock = l;
        self.lockDenied = false;
        if (l.addEventListener) {
          l.addEventListener('release', function () {
            if (self.lock === l) self.lock = null;
            self._emit();
          });
        }
        self._emit();
      })['catch'](function () {
        self.lockPending = false;
        self.lockDenied = true;
        self._emit();
      });
    } catch (e) {
      this.lockPending = false;
    }
  };

  WakeKeeper.prototype._watch = function () {
    var self = this;
    if (this.watching) return;
    this.watching = true;

    var again = function () {
      if (!self.wanted) return;
      if (document.visibilityState !== 'visible') return;
      if (self.video && self.video.paused) self._play();
      if (!self.lock) self._lock();
    };

    document.addEventListener('visibilitychange', again);
    // 页面切走又回来、被系统暂停、来电之后，都要续上
    window.addEventListener('pageshow', again);
    window.addEventListener('focus', again);
    this.timer = setInterval(again, 15000);
    // 用户随手点一下屏幕，就借这个手势再试一次（自动播放被拦时全靠它）
    document.addEventListener('touchend', again, true);
    document.addEventListener('click', again, true);
  };

  global.WakeKeeper = WakeKeeper;
})(window);
